package main

import (
	"fmt"
	"runtime"
	"time"
)

func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			out <- n
		}
	}()
	return out
}

func square(in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for n := range in {
			out <- n * n
		}
	}()
	return out
}

func main() {
	out := square(gen(1, 2, 3, 4, 5, 6))
	for i := 0; i < 3; i++ {
		fmt.Println(<-out)
	}
	time.Sleep(100 * time.Millisecond)
	fmt.Println("goroutines alive:", runtime.NumGoroutine())
}

package main

import (
	"fmt"
	"time"
)

func feed(vals ...int) <-chan int {
	c := make(chan int)
	go func() {
		defer close(c)
		for _, v := range vals {
			time.Sleep(10 * time.Millisecond)
			c <- v
		}
	}()
	return c
}

func merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	for _, c := range cs {
		go func() {
			defer close(out)
			for n := range c {
				out <- n
			}
		}()
	}
	return out
}

func main() {
	sum := 0
	for n := range merge(feed(1), feed(10, 20, 30)) {
		sum += n
	}
	fmt.Println("sum:", sum)
}
